(function(){
    var body = result;
    try {
        var j = JSON.parse(body);
        if (j.data) {
            var audio = j.data.audioUrl || j.data.url || j.data.playUrl || j.data.m4aUrl;
            if (audio && (audio.match(/\.(m4a|mp3|aac|ogg|flac|wav)(\?|$)/i) || audio.match(/^https?:\/\//))) {
                return audio;
            }
            return j.data.chapterBody || j.data.content || j.data.text || j.data.body || '';
        }
    } catch(e) {}
    if (body.match(/\.(m4a|mp3|aac|ogg|flac|wav)(\?|$)/i)) {
        return body.trim();
    }
    if (body.indexOf('<') !== -1 && body.indexOf('>') !== -1) {
        return body.replace(/<[^>]+>/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
    }
    return body;
})()

